import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.BybBnFXO.js";const p=JSON.parse('{"title":"GIA 4Cs (Diamond)","description":"","frontmatter":{"title":"GIA 4Cs (Diamond)","grading":"diamond-4cs"},"headers":[],"relativePath":"grading/diamond-4cs.md","filePath":"grading/diamond-4cs.md","lastUpdated":1785917625000}'),o={name:"grading/diamond-4cs.md"};function d(l,e,n,s,c,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="gia-4cs-diamond" tabindex="-1">GIA 4Cs (Diamond) <a class="header-anchor" href="#gia-4cs-diamond" aria-label="Permalink to &quot;GIA 4Cs (Diamond)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The world standard for diamond grading, established by GIA in 1953. Four independent measurements—carat, color, clarity, cut—jointly determine a polished diamond&#39;s market value.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Carat (ct): 1 ct = 0.2 g; 1 point = 0.01 ct. Rarity rises exponentially.</li><li>Color: D–Z scale, only the yellow/brown tint. D = colorless; Z = light.</li><li>Clarity: FL–I3 scale under 10×. Inclusions and blemishes determine grade.</li><li>Cut: Excellent → Poor. Proportions, symmetry, polish drive brilliance.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>D/IF/Excellent</td><td>auction-grade</td></tr><tr><td>sapphire</td><td>Cornflower Blue / Excellent</td><td>colored gems use colour + cut</td></tr></tbody></table><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',8)])])}const u=a(o,[["render",d]]);export{p as __pageData,u as default};
